-- Environment context schema. Generated by go run ./cmd/environment-schema.
CREATE TABLE IF NOT EXISTS `environment_object` (`id` bigint AUTO_INCREMENT,`group_id` bigint,`name` varchar(160),`kind` varchar(32),`description` text,`revision` bigint,`deleted` boolean,`updated_at` bigint,PRIMARY KEY (`id`),INDEX `idx_environment_object_group_id` (`group_id`),INDEX `idx_environment_object_deleted` (`deleted`));
CREATE TABLE IF NOT EXISTS `environment_relation` (`id` bigint AUTO_INCREMENT,`identity` varchar(64),`from_ref` varchar(100),`to_ref` varchar(100),`kind` varchar(32),`status` varchar(24),`from_version` varchar(64),`to_version` varchar(64),`source` varchar(32),`note` text,`valid_until` bigint,`created_by` bigint,`updated_by` bigint,`updated_at` bigint,`revision` bigint,PRIMARY KEY (`id`),INDEX `idx_environment_relation_to_ref` (`to_ref`),INDEX `idx_environment_relation_status` (`status`),INDEX `idx_environment_relation_from_ref` (`from_ref`),CONSTRAINT `uni_environment_relation_identity` UNIQUE (`identity`));
CREATE TABLE IF NOT EXISTS `environment_change` (`id` bigint AUTO_INCREMENT,`relation_id` bigint,`object_ref` varchar(100),`actor_id` bigint,`action` varchar(32),`detail` text,`created_at` bigint,PRIMARY KEY (`id`),INDEX `idx_environment_change_relation_id` (`relation_id`),INDEX `idx_environment_change_object_ref` (`object_ref`),INDEX `idx_environment_change_created_at` (`created_at`));
CREATE TABLE IF NOT EXISTS `environment_discovery` (`version_id` bigint,`actor_id` bigint,`state` varchar(24),`note` text,`next_run` bigint,`lease_until` bigint,`updated_at` bigint,PRIMARY KEY (`version_id`),INDEX `idx_environment_discovery_next_run` (`next_run`));
